async function getCommitTx() {
  // The commit tx was at block 2696557
  const tx = await provider.getTransaction('0x7a4651aad2bb4d3a2afe458ac420a4754665a1a1e9e93cbd6b3faed2599e760b');
  console.log('Commit transaction:');
  console.log('  hash:', tx.hash);
  console.log('  block:', tx.blockNumber);
  console.log('  to:', tx.to);
  console.log('  from:', tx.from);
  console.log('  input:', tx.input);
  console.log('  input length:', tx.input.length);
  console.log('  function selector:', tx.input.slice(0, 10));

  // The juryCommit function signature is: juryCommit(uint256 _caseId, bytes32 _commitHash)
  // selector: 0x4b229b4c
  console.log('\nParsing commit parameters...');

  if (tx.input.slice(0, 10) === '0x4b229b4c') {
    // caseId is at position 4-36 (uint256)
    const caseId = BigInt('0x' + tx.input.slice(10, 74));
    // commitHash is at position 36-68 (bytes32)
    const commitHash = '0x' + tx.input.slice(74, 138);
    console.log('  caseId:', caseId.toString());
    console.log('  commitHash:', commitHash);
  }
}

getCommitTx().catch(console.error);
